      "ms_sch1_5_desc": "गुणवत्ता नियंत्रण चाचणी क्षमता आणि उपकरणे तपासण्यासाठी नियुक्त BIS तांत्रिक अधिकारी कारखान्याला भेट देऊन नमुने घेतात.",
