      "ms_crs_3_title": "BIS-मान्यताप्राप्त भारतीय प्रयोगशाळेत अनिवार्य चाचणी",
      "ms_crs_3_desc": "भारतातील BIS-मान्यताप्राप्त प्रयोगशाळेतच नमुना चाचणी करणे आवश्यक आहे. अहवाल ९० दिवसांसाठी वैध असतात.",
