      "ms_crs_4_desc": "crsbis.in वर चाचणी अहवाल आणि शुल्कासह अर्ज करा. प्रत्यक्ष फॅक्टरी ऑडिटची आवश्यकता नाही (कागदविरहित SDoC).",
      "ms_crs_4_time": "3–5 दिवस",
