      "ms_cons_1_desc": "ISI चिन्हाखालील 7-अंकी CM/L क्रमांक, दागिन्यांवरील 6-अंकी HUID किंवा इलेक्ट्रॉनिक्सवरील R-क्रमांक शोधा.",
      "ms_cons_1_time": "1 मिनिट",
      "ms_cons_2_title": "केंद्रीय नोंदणी सक्रिय स्थिती तपासणी",
      "ms_cons_2_desc": "कोड सध्या चालू (OPERATIVE) आहे आणि कालबाह्य किंवा रद्द झालेला नाही याची खात्री करा.",
