      "default_template_badge": "ડિફૉલ્ટ નમૂનો",
      "no_data_found_for": "આના માટે કોઈ ડેટા મળ્યો નથી:",
      "ms_sch1_1_title": "લાગુ પ્રમાણભૂત ઓળખો અને QCO પુષ્ટિ કરો",
      "ms_sch1_1_desc": "ચોક્કસ ભારતીય માનક નક્કી કરો (દા.ત. રમકડાં માટે IS 9873). ઉત્પાદન ફરજિયાત ગુણવત્તા નિયંત્રણ ઓર્ડર (QCO) હેઠળ આવે છે કે નહીં તે ચકાસો.",
      "ms_sch1_1_time": "1–3 દિવસ",
      "ms_sch1_2_title": "NABL / BIS માન્યતા પ્રાપ્ત પ્રયોગશાળામાં નમૂના પરીક્ષણ",
      "ms_sch1_2_desc": "નમૂનાઓ બનાવો અને નિર્ધારિત ધોરણો અનુસાર સંપૂર્ણ પરીક્ષણ માટે BIS અથવા NABL માન્યતા પ્રાપ્ત પ્રયોગશાળામાં સબમિટ કરો.",
      "ms_sch1_2_time": "15–30 દિવસ (પરીક્ષણ ચક્ર પર આધારિત)",
      "ms_sch1_3_title": "માનક ઓનલાઇન દ્વારા ઓનલાઇન અરજી સબમિશન (ફોર્મ V)",
      "ms_sch1_3_desc": "www.manakonline.in પર ફોર્મ V ભરો. મશીનરી યાદી, કેલિબ્રેશન પ્રમાણપત્રો, ફેક્ટરી લેઆઉટ અને ટેસ્ટ રિપોર્ટ અપલોડ કરો.",
      "ms_sch1_3_time": "3–5 દિવસ",
      "ms_sch1_4_title": "અરજી અને માર્કિંગ ફી ચુકવણી (MSME છૂટછાટો લાગુ)",
      "ms_sch1_4_desc": "વૈધાનિક અરજી ફી અને માર્કિંગ ફી ચૂકવો. સૂક્ષ્મ સાહસોને 50% અને નાના સાહસોને 20% છૂટછાટ મળે છે.",
      "ms_sch1_4_time": "ત્વરિત ઓનલાઇન ચુકવણી",
      "ms_sch1_5_title": "ઓન-સાઇટ ફેક્ટરી નિરીક્ષણ અને ચકાસણી ઓડિટ",
      "ms_sch1_5_desc": "ગુણવત્તા નિયંત્રણ પરીક્ષણ ક્ષમતા અને સાધનોની ચકાસણી માટે નિયુક્ત BIS ટેકનિકલ અધિકારી ફેક્ટરીની મુલાકાત લે છે અને નમૂનાઓ લે છે.",
      "ms_sch1_5_time": "અરજી સ્વીકાર્યા પછી 10–20 દિવસ",
      "ms_sch1_6_title": "લાયસન્સ મંજૂરી (CM/L નંબર) અને ISI માર્ક અધિકૃતતા",
      "ms_sch1_6_desc": "સફળ ઓડિટ અને પાસ લેબ રિપોર્ટ્સ પછી, BIS 7-અંકનું લાયસન્સ (CM/L-XXXXXXX) આપે છે. ISI માર્ક લગાવવાની કાનૂની મંજૂરી મળે છે.",
      "ms_sch1_6_time": "કુલ પ્રક્રિયા 35–65 દિવસ",
      "ms_crs_1_title": "MeitY / BIS CRO શેડ્યૂલમાં ઉત્પાદન કવરેજ તપાસો",
      "ms_crs_1_desc": "ઇલેક્ટ્રોનિક્સ અને IT માલના ફરજિયાત નોંધણી આદેશ હેઠળ કેટેગરી ચકાસો (દા.ત. IS 16046 હેઠળ પાવર બેંક).",
      "ms_crs_1_time": "1–2 દિવસ",
      "ms_crs_2_title": "અધિકૃત ભારતીય પ્રતિનિધિ (AIR) ની નિમણૂક",
      "ms_crs_2_desc": "વિદેશી ઉત્પાદકોએ ભારતમાં રહેતા અધિકૃત ભારતીય પ્રતિનિધિ (AIR) ની કાનૂની નિમણૂક કરવી જરૂરી છે.",
      "ms_crs_2_time": "3–7 દિવસ",
      "ms_crs_3_title": "BIS-માન્ય ભારતીય પ્રયોગશાળામાં ફરજિયાત પરીક્ષણ",
      "ms_crs_3_desc": "ભારતમાં આવેલી BIS-માન્ય લેબમાં જ પરીક્ષણ કરાવવું જરૂરી છે. રિપોર્ટ્સ 90 દિવસ માટે માન્ય છે.",
      "ms_crs_3_time": "15–25 દિવસ",
      "ms_crs_4_title": "સ્વ-ઘોષણા (SDoC) પોર્ટલ સબમિશન",
      "ms_crs_4_desc": "ટેસ્ટ રિપોર્ટ્સ અને ફી સાથે crsbis.in પર અરજી કરો. કોઈ ફેક્ટરી ઓડિટની જરૂર નથી (કાગળ રહિત SDoC).",
      "ms_crs_4_time": "3–5 દિવસ",
      "ms_crs_5_title": "યુનિક રજીસ્ટ્રેશન નંબર (R-નંબર) જારી કરવો",
      "ms_crs_5_desc": "BIS 8-અંકનો રજીસ્ટ્રેશન નંબર (દા.ત. R-41001234) જારી કરે છે. CRS લોગો સાથે ઉત્પાદનો વેચી શકાય છે.",
      "ms_crs_5_time": "રિપોર્ટ અપલોડથી 15–20 દિવસ",
      "ms_cons_1_title": "ઓળખ કોડ મેળવવો",
      "ms_cons_1_desc": "ISI માર્ક નીચે 7-અંકનો CM/L નંબર, સોના પર 6-અંકનો HUID અથવા ઇલેક્ટ્રોનિક્સ પર R-નંબર શોધો.",
      "ms_cons_1_time": "1 મિનિટ",
      "ms_cons_2_title": "સેન્ટ્રલ રજિસ્ટ્રી સ્ટેટસ ચેક",
      "ms_cons_2_desc": "કોડ હાલમાં સક્રિય (OPERATIVE) છે અને રદ કે સમાપ્ત થયેલ નથી તેની ખાતરી કરો.",
      "ms_cons_2_time": "ત્વરિત",
      "ms_cons_3_title": "લાયસન્સધારકની ઓળખ અને ઉત્પાદન ઓડિટ",
      "ms_cons_3_desc": "પેકેજિંગ લેબલ સાથે બ્રાન્ડ નામ, ઉત્પાદકની વિગતો અને ઉત્પાદન વિશિષ્ટતાઓની તુલના કરો.",
      "ms_cons_3_time": "5 મિનિટ",
      "ms_cons_4_title": "પ્રમાણિકતા પુષ્ટિ / ફરિયાદ નિવારણ",
      "ms_cons_4_desc": "જો અસલી હોય તો ખરીદીનો પુરાવો રાખો. જો નકલી કે હલકી ગુણવત્તાવાળું હોય, તો BIS કેર એપ પર ફરિયાદ કરો.",
