      "default_template_banner_title": "ಡೀಫಾಲ್ಟ್ ಯೋಜನೆ-I ಮಾದರಿ • ನಿಮ್ಮ ಸ್ವಂತ ಭಾರತೀಯ ಮಾನದಂಡವನ್ನು (ISI) ಆಯ್ಕೆಮಾಡಿ",
      "default_template_banner_desc": "ನೀವು ಪ್ರಸ್ತುತ ಸಾಮಾನ್ಯ ಯೋಜನೆ-I ಪ್ರಮಾಣೀಕರಣ ಅನುಕ್ರಮವನ್ನು ವೀಕ್ಷಿಸುತ್ತಿದ್ದೀರಿ. ಮೈಲಿಗಲ್ಲುಗಳು, ಕಡ್ಡಾಯ QCOಗಳು ಮತ್ತು ಪರೀಕ್ಷಾ ಪ್ರಯೋಗಾಲಯಗಳನ್ನು ಕಸ್ಟಮೈಸ್ ಮಾಡಲು ಕೆಳಗೆ ಉತ್ಪನ್ನವನ್ನು ಆಯ್ಕೆಮಾಡಿ ಅಥವಾ IS ಕೋಡ್ ನಮೂದಿಸಿ.",
