      "empty_journey_verify_title": "ಪರಿಶೀಲಿಸಲು ಪರವಾನಗಿ ಅಥವಾ ಹಾಲ್‌ಮಾರ್ಕ್ ನಮೂದಿಸಿ",
      "empty_journey_cert_desc": "ಕೆಳಗಿನ ಸಾಮಾನ್ಯ ಭಾರತೀಯ ಮಾನದಂಡಗಳಲ್ಲಿ ಒಂದನ್ನು ಆರಿಸಿ ಅಥವಾ ಹುಡುಕಾಟ ಪೆಟ್ಟಿಗೆಯಲ್ಲಿ IS ಕೋಡ್ ನಮೂದಿಸಿ.",
      "empty_journey_verify_desc": "ಗ್ರಾಹಕರ ರಕ್ಷಣೆಗಾಗಿ ಹಂತ-ಹಂತದ ಪರಿಶೀಲನೆ ಮತ್ತು ದೃಢೀಕರಣವನ್ನು ಟ್ರ್ಯಾಕ್ ಮಾಡಿ.",
