      "ms_sch1_1_title": "ബാധകമായ മാനദണ്ഡം തിരിച്ചറിഞ്ഞ് QCO സ്ഥിരീകരിക്കുക",
      "ms_sch1_1_desc": "കൃത്യമായ ഇന്ത്യൻ സ്റ്റാൻഡേർഡ് നിർണ്ണയിക്കുക (ഉദാ. കളിപ്പാട്ടങ്ങൾക്ക് IS 9873). ഉൽപ്പന്നം നിർബന്ധിത ക്വാളിറ്റി കൺട്രോൾ ഓർഡറിന് (QCO) കീഴിലാണോ എന്ന് സ്ഥിരീകരിക്കുക.",
      "ms_sch1_1_time": "1–3 ദിവസം",
      "ms_sch1_2_title": "NABL / BIS അംഗീകൃത ലബോറട്ടറിയിലെ സാമ്പിൾ പരിശോധന",
      "ms_sch1_2_desc": "സാമ്പിളുകൾ നിർമ്മിച്ച് നിർദ്ദിഷ്ട മാനദണ്ഡങ്ങൾക്കനുസൃതമായി പൂർണ്ണ പരിശോധനയ്ക്കായി BIS അല്ലെങ്കിൽ NABL അംഗീകൃത ലാബിൽ സമർപ്പിക്കുക.",
      "ms_sch1_2_time": "15–30 ദിവസം (പരിശോധനാ ചക്രത്തെ ആശ്രയിച്ചിരിക്കുന്നു)",
      "ms_sch1_3_title": "മാനക് ഓൺലൈൻ വഴി ഓൺലൈൻ അപേക്ഷ സമർപ്പിക്കൽ (ഫോം V)",
      "ms_sch1_3_desc": "www.manakonline.in-ൽ ഫോം V ഫയൽ ചെയ്യുക. യന്ത്രങ്ങളുടെ ലിസ്റ്റ്, കാലിബ്രേഷൻ സർട്ടിഫിക്കറ്റുകൾ, ലേഔട്ട്, ടെസ്റ്റ് റിപ്പോർട്ടുകൾ എന്നിവ അപ്‌ലോഡ് ചെയ്യുക.",
      "ms_sch1_3_time": "3–5 ദിവസം",
      "ms_sch1_4_title": "അപേക്ഷ, അടയാളപ്പെടുത്തൽ ഫീസ് അടയ്ക്കൽ (MSME ഇളവുകൾ ബാധകം)",
      "ms_sch1_4_desc": "നിയമപരമായ അപേക്ഷാ ഫീസും മാർക്കിംഗ് ഫീസും അടയ്ക്കുക. മൈക്രോ സംരംഭങ്ങൾക്ക് 50% ഇളവും ചെറുകിട സംരംഭങ്ങൾക്ക് 20% ഇളവും ലഭിക്കും.",
      "ms_sch1_4_time": "തൽക്ഷണ ഓൺലൈൻ പേയ്മെന്റ്",
      "ms_sch1_5_title": "ഓൺ-സൈറ്റ് ഫാക്ടറി പരിശോധനയും ഓഡിറ്റും",
      "ms_sch1_5_desc": "ഗുണനിലവാര നിയന്ത്രണ സംവിധാനങ്ങൾ പരിശോധിക്കാൻ നിർദ്ദിഷ്ട BIS സാങ്കേതിക ഉദ്യോഗസ്ഥൻ ഫാക്ടറി സന്ദർശിച്ച് സാമ്പിളുകൾ ശേഖരിക്കുന്നു.",
