      "ms_sch1_6_title": "ലൈസൻസ് അനുവദിക്കൽ (CM/L നമ്പർ) & ISI മാർക്ക് അംഗീകാരം",
      "ms_sch1_6_desc": "വിജയകരമായ പരിശോധനയ്ക്ക് ശേഷം, BIS 7 അക്ക സർട്ടിഫിക്കേഷൻ ലൈസൻസ് (CM/L-XXXXXXX) നൽകുന്നു. ഉൽപ്പന്നങ്ങളിൽ ISI മാർക്ക് ഉപയോഗിക്കാൻ അനുമതി ലഭിക്കുന്നു.",
      "ms_sch1_6_time": "ആകെ പ്രക്രിയ 35–65 ദിവസം",
