      "ms_crs_1_desc": "ഇലക്ട്രോണിക്സ് & ഐടി ഗുഡ്സ് നിർബന്ധിത രജിസ്ട്രേഷൻ ഉത്തരവിന് കീഴിലുള്ള വിഭാഗം പരിശോധിക്കുക (ഉദാ. IS 16046 പ്രകാരം പവർ ബാങ്ക്).",
