      "ms_crs_2_desc": "വിദേശ നിർമ്മാതാക്കൾ ഇന്ത്യയിൽ താമസിക്കുന്ന ഒരു അംഗീകൃത ഇന്ത്യൻ പ്രതിനിധിയെ (AIR) നിയമപരമായി നാമനിർദ്ദേശം ചെയ്യണം.",
      "ms_crs_2_time": "3–7 ദിവസം",
