      "ms_crs_3_desc": "ഇന്ത്യയിലുള്ള ബിഐഎസ് അംഗീകൃത ലാബിൽ മാത്രമേ പരിശോധന നടത്താവൂ. റിപ്പോർട്ടുകൾക്ക് 90 ദിവസത്തെ സാധുതയുണ്ട്.",
      "ms_crs_3_time": "15–25 ദിവസം",
