      "ms_crs_4_desc": "ടെസ്റ്റ് റിപ്പോർട്ടുകളും ഫീസുമായി crsbis.in-ൽ അപേക്ഷിക്കുക. ഫാക്ടറി ഓഡിറ്റ് ആവശ്യമില്ല (പേപ്പർ രഹിത SDoC).",
