      "ms_crs_5_time": "റിപ്പോർട്ട് അപ്‌ലോഡിൽ നിന്ന് 15–20 ദിവസം",
      "ms_cons_1_title": "തിരിച്ചറിയൽ കോഡ് കണ്ടെത്തൽ",
      "ms_cons_1_desc": "ISI മാർക്കിന് താഴെയുള്ള 7 അക്ക CM/L നമ്പർ, സ്വർണ്ണത്തിലെ 6 അക്ക HUID അല്ലെങ്കിൽ ഇലക്ട്രോണിക്സിലെ R-നമ്പർ കണ്ടെത്തുക.",
      "ms_cons_1_time": "1 മിനിറ്റ്",
      "ms_cons_2_title": "സെൻട്രൽ രജിസ്ട്രി സ്റ്റാറ്റസ് പരിശോധന",
      "ms_cons_2_desc": "കോഡ് നിലവിൽ സജീവമാണോ (OPERATIVE) എന്ന് പരിശോധിച്ച് ഉറപ്പാക്കുക.",
