      "ms_cons_3_desc": "ബ്രാൻഡ് പേര്, നിർമ്മാതാവിന്റെ വിവരങ്ങൾ, ഉൽപ്പന്ന സവിശേഷതകൾ എന്നിവ ലേബലുകളുമായി ഒത്തുനോക്കുക.",
