      "ms_cons_4_title": "ആധികാരികത സ്ഥിരീകരിക്കൽ / പരാതി പരിഹാരം",
      "ms_cons_4_desc": "ഒറിജിനലാണെങ്കിൽ ബിൽ സൂക്ഷിക്കുക. വ്യാജമാണെങ്കിൽ BIS കെയർ ആപ്പിൽ പരാതി നൽകുക.",
